#include "rpg/pve_visual.hpp"
#include "rpg/battle_presentation.hpp"
#include <iostream>
#include <stdexcept>
using namespace rpg;using namespace rpg::presentation;
void check(bool value,const char* why){if(!value){throw std::runtime_error(why);}}
const Fighter& unit(const Snapshot& s,std::string_view id){const auto i=std::ranges::find(s.fighters,id,[](const Fighter& f){return f.definition.id;});if(i==s.fighters.end()){throw std::runtime_error("Missing fighter");}return *i;}
WaveVisualDefinition fast(){auto d=wave_lab_definition();for(auto& e:d.stage.encounters){e.enemies[0].max_health=1;e.enemies[0].stats.block=0;}return d;}
void initial(){WaveVisualSession s;const auto h=s.hud();check(h.wave_number==1&&h.wave_count==2&&h.global_actions==0&&h.global_remaining==200&&h.local_actions==0&&!h.previous_wave,"initial wave counters");check(s.state().abilities.size()==3&&ability_card(s.state(),2).badge==AbilityBadge::Passive,"kit preserved");}
void purity(){WaveVisualSession s;const auto before=s.observation();for(int i=0;i<50;++i){static_cast<void>(s.state());static_cast<void>(s.hud());}check(s.observation()==before&&s.transition_events().empty(),"reads cannot advance waves");}
void boundary(){WaveVisualSession s(fast());check(s.submit(0,1,"ECO-1").accepted(),"first wave action");const auto h=s.hud();check(h.wave_number==2&&h.wave_count==2&&h.global_actions==1&&h.local_actions==0&&h.previous_wave=="onda-ECO-1"&&h.wave_id=="onda-ECO-2","boundary resets only local actions");check(!s.finished()&&s.state().revision==1,"not complete before final wave");const auto before=s.observation();check(s.submit(0,1,"ECO-2").error==VisualError::StaleCommand&&s.observation()==before,"old-wave input invalid");check(!s.submit(1,1,"ECO-1").accepted()&&s.observation()==before,"old enemy cannot be selected");}
void completion(){WaveVisualSession s(fast());check(s.submit(0,1,"ECO-1").accepted()&&s.submit(1,1,"ECO-2").accepted(),"two waves");const auto h=s.hud();check(h.finished&&h.objective_met&&h.wave_number==2&&h.global_actions==2,"only final wave completes");check(s.submit(2,1,"ECO-2").error==VisualError::Finished,"post-stage command rejected");check(s.state().progress.credits==0,"no generic rewards");}
void core_carry(){auto d=fast();d.stage.squad[0].max_health=20000;auto expected=d.stage;for(auto& e:expected.encounters){e.rules.guard_enabled=false;}Stage core(expected);WaveVisualSession view(d);check(core.apply({"FELIPE",ActionType::Skill,"ECO-1","FELIPE-A3"}).action.accepted()&&view.submit(0,3,"ECO-1").accepted(),"matching transition action");const auto state=view.observation();const auto& actual=unit(state.battle,"FELIPE");const auto* baseline=core.battle().find("FELIPE");check(actual.health==baseline->health&&actual.cooldowns==baseline->cooldowns&&actual.vigil_charges==baseline->vigil_charges&&actual.statuses==baseline->statuses,"carry remains core responsibility");check(view.transition_events().size()==1&&view.transition_events()[0].status_kind==EffectKind::Heal,"one authoritative wave heal event");}
void global_limit(){auto d=wave_lab_definition();d.stage.global_budget=ActionBudget{1,LimitOutcome::Draw};WaveVisualSession s(d);check(s.submit(0,1,"ECO-1").accepted(),"limit action");check(s.finished()&&!s.hud().objective_met&&s.hud().global_remaining==0&&s.observation().end_reason==StageEndReason::GlobalActionLimit,"global limit not success");}
void restart(){WaveVisualSession s(fast());check(s.submit(0,1,"ECO-1").accepted(),"reach wave two");s.abandon();const auto before=s.observation();check(s.submit(1,1,"ECO-2").error==VisualError::SafetyStop&&s.observation()==before,"abandon inert");s.reset();check(s.hud().wave_number==1&&s.state().progress.attempt==2&&!s.hud().previous_wave&&s.transition_events().empty(),"reset clears transition feedback");check(s.submit(0,1,"ECO-1").error==VisualError::StaleCommand,"reset invalidates input");}
void full_waves(){WaveVisualSession s;for(int i=0;i<220&&!s.finished();++i){const auto v=s.state();if(v.automatic){check(s.step_automatic().accepted(),"wave enemy");}else{const auto enemies=target_candidates(v,1);check(!enemies.empty()&&s.submit(v.revision,1,enemies[0]).accepted(),"wave player");}}check(s.finished()&&s.hud().objective_met,"full waves playable");}
void no_kit_change(){PveVisualSession s(phased_ritual_lab_definition());const auto before=s.observation().battle.rules.skills;check(s.submit(0,1,"ECO-1").accepted(),"phase A1");check(s.observation().phase_id=="Vigilia-90"&&s.observation().battle.rules.skills==before&&s.phase_events().size()==1,"phase without changed skills");}
void changed_kit(){PveVisualSession s(phased_ritual_lab_definition());check(s.submit(0,3,"ECO-1").accepted(),"phase A3");const auto o=s.observation();const auto skill=std::ranges::find(o.battle.rules.skills,std::string("ECO-1-A1"),&SkillDefinition::id);check(o.phase_id=="Furia-60"&&s.phase_events().size()==2&&s.phase_events()[0].id=="Vigilia-90"&&s.phase_events()[1].id=="Furia-60","ordered phase feedback");check(skill!=o.battle.rules.skills.end()&&skill->effects[0].power_ratio==15000,"same skill identity with new strength");const auto enemy_before=unit(o.battle,"FELIPE").health;check(s.step_automatic().accepted(),"new boss kit automatic");check(unit(s.observation().battle,"FELIPE").health<enemy_before,"new kit executes");}
void phase_reset(){PveVisualSession s(phased_ritual_lab_definition());check(s.submit(0,3,"ECO-1").accepted(),"trigger phases");const auto snapshot=s.observation();const auto events=s.phase_events().size();for(int i=0;i<20;++i){static_cast<void>(pve_hud(s.observation()));}check(s.observation()==snapshot&&s.phase_events().size()==events,"feedback not replayed by read");s.reset();check(s.phase_events().empty()&&!s.observation().phase_id,"phase reset");}
void isolated(){VisualSession normal(terminal_lab_setup());PveVisualSession ritual;WaveVisualSession waves(fast());const auto normal_before=normal.state();const auto ritual_before=ritual.observation();check(waves.submit(0,1,"ECO-1").accepted(),"wave isolated action");check(normal.state().combat==normal_before.combat&&ritual.observation()==ritual_before,"other tests isolated");}
void invalid(){auto d=wave_lab_definition();d.loadouts.pop_back();bool caught=false;try{WaveVisualSession bad(d);}catch(const std::invalid_argument&){caught=true;}check(caught,"catalog count validated");}
int main(){try{initial();purity();boundary();completion();core_carry();global_limit();restart();full_waves();no_kit_change();changed_kit();phase_reset();isolated();invalid();std::cout<<"REG_TRANSITION_VISUAL_TESTS_RESULT passed=13 total=13\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}